<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {Download,Check} from 'lucide-vue-next';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {createNote,reviewNote} from '../api/notes';import {download} from '../api/client';import Notice from '../components/common/Notice.vue';import RunSummary from '../components/RunSummary.vue';import {ReviewStatus} from '../constants/enums';import {time} from '../utils/format';const s=useResearchData(),auth=useAuth(),a=useAction(),route=useRoute(),selected=ref(Number(route.query.run)||0),title=ref(''),interpretation=ref(''),proposal=ref(''),reviews=ref<Record<number,string>>({});const runs=computed(()=>s.runs.filter(r=>r.status==='completed')),run=computed(()=>runs.value.find(r=>r.id===selected.value)||runs.value[0]),notes=computed(()=>s.notes.filter(n=>n.run_id===run.value?.id));function submit(){a.execute(async()=>{await createNote({run_id:run.value!.id,title:title.value,interpretation:interpretation.value,proposal:proposal.value});title.value='';interpretation.value='';proposal.value='';await s.refresh()})}function review(id:number,status:string){a.execute(async()=>{await reviewNote(id,{status,review_note:reviews.value[id]});await s.refresh()})}function exportRun(id:number){a.execute(async()=>{await download(`/runs/${id}/export`,`spectral-run-${id}.csv`)})}</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">REPLICATION REVIEW / 05</p><h1>复配审阅<span>比例是待验证的材料假设，不是成分保证。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><label>关联解混研究<select aria-label="关联解混研究" :value="run?.id||''" @change="selected=Number(($event.target as HTMLSelectElement).value)"><option v-for="r in runs" :key="r.id" :value="r.id">#{{r.id}} / {{r.name}}</option></select></label><RunSummary v-if="run" :run="run"/><div class="notes-grid"><section><h2>提交复配验证建议</h2><form v-if="auth.user?.role!=='viewer'" @submit.prevent="submit"><label>建议标题<input aria-label="建议标题" v-model="title" minlength="2" required placeholder="例如：首批矿物小样复配验证"/></label><label>配比与边界解释<textarea aria-label="配比解释" v-model="interpretation" minlength="8" required placeholder="说明端元条件、残差和条件分位范围的适用边界。"/></label><label>复配验证方案<textarea aria-label="复配方案" v-model="proposal" minlength="8" required placeholder="记录独立复配与重新测谱计划。"/></label><button class="primary" :disabled="a.busy.value||!run">提交材料负责人</button></form><p v-else class="role-note">阅读者可查阅复配建议，获批后可下载配比CSV。</p></section><section class="note-list"><h2>审阅档案</h2><article v-for="n in notes" :key="n.id"><div class="note-title"><span class="eyebrow">NOTE-{{n.id}} / RUN-{{n.run_id}}</span><span :class="['review-badge',n.status]">{{ReviewStatus[n.status as keyof typeof ReviewStatus]}}</span></div><h3>{{n.title}}</h3><p><b>解释</b>{{n.interpretation}}</p><p><b>验证</b>{{n.proposal}}</p><small>{{n.owner}} · {{time(n.created_at)}}</small><div v-if="n.status==='submitted'&&auth.user?.role==='admin'" class="approval-form"><label>审阅意见<textarea :aria-label="'审阅意见 '+n.id" v-model="reviews[n.id]" minlength="8" placeholder="至少8字，说明端元/噪声假设和批准范围。"/></label><div><button class="primary" :disabled="a.busy.value||(reviews[n.id]||'').length<8" @click="review(n.id,'approved')"><Check :size="14"/>批准研究归档</button><button class="outline" :disabled="a.busy.value||(reviews[n.id]||'').length<8" @click="review(n.id,'rejected')">退回复配</button></div></div><div v-if="n.status!=='submitted'" class="review-note"><b>{{n.reviewer}}</b><p>{{n.review_note}}</p></div><button v-if="n.status==='approved'" class="text-link" @click="exportRun(n.run_id)"><Download :size="14"/>下载获批CSV</button></article><p v-if="!notes.length" class="empty">还没有复配建议。研究员提交后，由材料负责人审阅。</p></section></div></div></template>
